import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { ZTemplateFeature } from './z-template-feature/ztemplate-feature';
import { MenuModuleIndex } from '@_core/_route/menu-module-index/menu-module-index';
import { EP } from '@_core/_client';

const routes: Routes = [
  {
    path: '',
    component: ZTemplateFeature,
    children: [
      {
        path: '',
        redirectTo: 'index',
        pathMatch: 'full',
      },
      {
        path: 'index',
        component: MenuModuleIndex,
        data: {
          title: 'Feature Module',
          linkPaginate: ``,
          linkAdd: ``,
          linkUpdate: ``,
          permission: [EP.Gets],
          layer: ['Module', 'Feature'],
        },
      },
      {
        path: 'user',
        loadChildren: () => import('./userz/userz.module').then((m) => m.UserzModule),
      },
      {
        path: 'account-in',
        loadChildren: () => import('./account-in/account-in.module').then((m) => m.AccountInModule),
      },
      {
        path: 'account-out',
        loadChildren: () =>
          import('./account-out/account-out.module').then((m) => m.AccountOutModule),
      },
      {
        path: 'edu',
        loadChildren: () => import('./edu/edu.module').then((m) => m.EduModule),
      },
      {
        path: 'library',
        loadChildren: () =>
          import('./edu-library/edu-library-module').then((m) => m.EduLibraryModule),
      },
      {
        path: 'exam',
        loadChildren: () => import('./edu-exam/edu-exam.module').then((m) => m.EduExamModule),
      },
      {
        path: 'syllabus',
        loadChildren: () =>
          import('./edu-syllabus/edu-syllabus.module').then((m) => m.EduSyllabusModule),
      },
      {
        path: 'question-bank',
        loadChildren: () =>
          import('./edu-question/edu-question-module').then((m) => m.EduQuestionModule),
      },
      {
        path: 'file-upload',
        loadChildren: () =>
          import('./file-upload/file-upload.module').then((m) => m.FileUploadModule),
      },
      {
        path: 'notification',
        loadChildren: () =>
          import('./notification/notification.module').then((m) => m.NotificationModule),
      },
    ],
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class FeatureRoutingModule {
}
